  $products$::jsonb) LOOP
    SELECT id INTO v_id
    FROM catalogue_produits
    WHERE categorie = 'pac_air_eau'
      AND reference = p->>'reference'
    ORDER BY created_at NULLS LAST
    LIMIT 1;

    IF v_id IS NULL THEN
      INSERT INTO catalogue_produits (
        entreprise_id, categorie, nom, marque, reference, description,
        caracteristiques, prix_unitaire_ht, unite, tva_taux,
        eligible_mpr, eligible_cee, fiche_cee, actif
      ) VALUES (
        v_entreprise,
        'pac_air_eau',
        p->>'nom',
        COALESCE(p->>'marque',''),
        p->>'reference',
        COALESCE(p->>'description',''),
        COALESCE(p->'caracteristiques','{}'::jsonb) ||
          jsonb_build_object(
            'pose_non_fournie_dans_source', true,
            'aides_a_verifier_sur_fiche_officielle', true
          ),
        CASE WHEN p->'prix_unitaire_ht' IS NOT NULL AND p->>'prix_unitaire_ht' <> 'null'
          THEN (p->>'prix_unitaire_ht')::numeric ELSE 0 END,
        COALESCE(p->>'unite','unite'),
        20,
        false,
        false,
        '',
        true
      );
    ELSE
      UPDATE catalogue_produits
      SET nom = p->>'nom',
          marque = COALESCE(NULLIF(p->>'marque',''), marque),
          description = COALESCE(NULLIF(p->>'description',''), description),
          caracteristiques = COALESCE(caracteristiques,'{}'::jsonb) ||
            COALESCE(p->'caracteristiques','{}'::jsonb) ||
            jsonb_build_object(
              'pose_non_fournie_dans_source', true,
              'aides_a_verifier_sur_fiche_officielle', true
            ),
          prix_unitaire_ht = CASE
            WHEN p->'prix_unitaire_ht' IS NOT NULL AND p->>'prix_unitaire_ht' <> 'null'
              THEN (p->>'prix_unitaire_ht')::numeric
            ELSE prix_unitaire_ht
          END,
          actif = true
      WHERE id = v_id;
    END IF;
    v_id := NULL;
  END LOOP;
END $$;
